styles.cssStarter:
:root{--accent:#111111;--bg:#ffffff;--dark:#100d0e;--ink:#111111;--muted:#7a7672;--line:#e6e3df;--surface-alt:#f5f4f2;--container:1280px;--gutter:32px;--section-y:120px;--radius:0px}
body{font-family:'Manrope',sans-serif;font-size:16px;line-height:1.7;color:var(--muted);background:var(--bg)}
.container{max-width:var(--container);padding:0 var(--gutter);margin:0 auto}
section{padding:var(--section-y) 0}
h1,h2,h3{font-family:'Manrope',sans-serif;font-weight:400;color:var(--ink);letter-spacing:-.02em}
h1{font-size:64px;line-height:1.1}
h2{font-size:44px;line-height:1.15}
h3{font-size:22px;line-height:1.3;font-weight:500}
.eyebrow{display:inline-flex;align-items:center;gap:8px;font-size:12px;color:var(--muted)}
.eyebrow::before{content:'';width:6px;height:6px;background:currentColor}
.btn{display:inline-flex;align-items:center;gap:10px;height:48px;padding:0 22px;background:var(--dark);color:#fff;font-size:14px;font-weight:500;border-radius:var(--radius)}
.btn-light{background:#fff;color:var(--ink)}
.dark{background:var(--dark);color:#bdb8b3}.dark h2,.dark h3{color:#fff}
.list-row{display:flex;justify-content:space-between;padding:22px 0;border-bottom:1px solid var(--line)}
@media(max-width:768px){:root{--section-y:72px;--gutter:20px}h1{font-size:40px}h2{font-size:32px}}

:root{--accent:#b08968;--primary:#1f4a4a;--ink:#1d1a17;--body:#5d5750;--sand:#e7ded6;--cream:#f7f3ec;--bg:#ffffff;--line:#e2dad2;--container:1280px;--gutter:32px;--section-y:120px;--radius:4px}
