h2{font-size:40px;line-height:1.25;text-align:center}
h2 em,h1 em{font-style:normal;color:var(--accent)}
h3{font-size:22px;line-height:1.35}
.eyebrow{display:inline-block;font-size:12px;font-weight:500;letter-spacing:.08em;text-transform:uppercase;color:var(--ink);border-bottom:1px solid var(--ink);padding-bottom:4px;margin-bottom:16px}
.btn{display:inline-flex;align-items:center;gap:8px;height:46px;padding:0 24px;border-radius:var(--radius);background:var(--primary);color:#fff;font-size:14px;font-weight:500}
.btn-accent{background:var(--accent)}
.btn-outline{background:transparent;border:1px solid #fff;color:#fff}
.stat{font-family:'Inter',sans-serif;font-size:40px;font-weight:500;color:var(--ink)}
.card{background:var(--bg);border-radius:var(--radius);overflow:hidden}
footer{background:var(--primary);color:#cfd9d6}
@media(max-width:768px){:root{--section-y:72px;--gutter:20px}h1{font-size:36px}h2{font-size:30px}}

